const FROM = process.env.MAIL_FROM || `${SITE_NAME} <[email redacted]>`;
const REPLY_TO = process.env.MAIL_REPLY_TO || '[email redacted]';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Toronto', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const daysOld = (d) => Math.round((Date.parse(today) - Date.parse(d)) / 86400000);

async function resend(method, p, body) {
